const $=(s,p=document)=>p.querySelector(s);const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const toast=(message)=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)};
const state={pets:[{id:'milo',name:'Milo',type:'Dog',photos:[],note:'',twinReady:false}],activePetId:'milo',brandReady:false,bag:0};
const activePet=()=>state.pets.find(p=>p.id===state.activePetId);const safeId=name=>`${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${Date.now().toString(36).slice(-4)}`;
function syncPetUI(){const pet=activePet(),name=pet.name||'Your pet',initial=name[0].toUpperCase();$('#petName').value=name;$('#petType').value=pet.type;$$('.name-copy').forEach(x=>x.textContent=name.toUpperCase());$$('.chat-pet-name').forEach(x=>x.textContent=name);$('#portraitName').textContent=name.toUpperCase();$$('.bandana,.owner-mark').forEach(x=>x.textContent=initial);$$('.scarf-shape').forEach(x=>x.childNodes[0].nodeValue=initial);$$('.product-link').forEach(a=>{const url=new URL(a.href);url.searchParams.set('pet',name);a.href=url.pathname+url.search});$('#photoTray').innerHTML='';pet.photos.forEach(addPhotoCard);updatePhotoStatus();renderPetSwitcher();$('#twinStatus').textContent=pet.twinReady?'Size confidence · 92%':'Waiting for photos';$('#twinStatus').classList.toggle('pending',!pet.twinReady)}
function renderPetSwitcher(){const wrap=$('#petSwitcher');wrap.querySelectorAll('.pet-chip').forEach(x=>x.remove());state.pets.forEach(p=>{const b=document.createElement('button');b.className=`pet-chip ${p.id===state.activePetId?'active':''}`;b.dataset.petId=p.id;b.innerHTML=`<span class="pet-avatar">${p.name[0].toUpperCase()}</span><span><b>${p.name}</b><small>${p.id===state.activePetId?'Active profile':p.type}</small></span>`;b.addEventListener('click',()=>{state.activePetId=p.id;state.brandReady=false;syncPetUI();toast(`Now designing for ${p.name}`)});wrap.insertBefore(b,$('#addPet'))})}
$('#addPet').addEventListener('click',()=>{$('#petModal').hidden=false;setTimeout(()=>$('#newPetName').focus(),50)});$('#closePetModal').addEventListener('click',()=>$('#petModal').hidden=true);$('#petModal').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.hidden=true});$('#petForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#newPetName').value.trim();if(!name)return;const pet={id:safeId(name),name,type:$('#newPetType').value,photos:[],note:'',twinReady:false};state.pets.push(pet);state.activePetId=pet.id;e.currentTarget.reset();$('#petModal').hidden=true;syncPetUI();toast(`${name} has a new profile`)});
$('#petName').addEventListener('input',e=>{activePet().name=e.target.value||'Your pet';syncPetUI()});$('#petType').addEventListener('change',e=>activePet().type=e.target.value);$('#measureToggle').addEventListener('click',e=>{const panel=$('#measurements');panel.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',panel.classList.contains('open'));e.currentTarget.textContent=panel.classList.contains('open')?'− Hide measurements':'＋ Add measurements for a more precise fit'});
$('#attachPhotos').addEventListener('click',()=>$('#petPhotos').click());$('#petPhotos').addEventListener('change',async e=>{const files=[...e.target.files].slice(0,8-activePet().photos.length);for(const file of files){if(!file.type.startsWith('image/'))continue;const data=await fileToData(file);activePet().photos.push({name:file.name,url:data});addPhotoCard(activePet().photos.at(-1))}updatePhotoStatus();e.target.value='';if(files.length)toast(`${files.length} photo${files.length>1?'s':''} attached`)});const fileToData=file=>new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)});
function addPhotoCard(photo){const item=document.createElement('div');item.className='photo-thumb';item.innerHTML=`<img alt="Pet reference photo" src="${photo.url}"><button aria-label="Remove photo">×</button>`;item.querySelector('button').addEventListener('click',()=>{activePet().photos=activePet().photos.filter(x=>x!==photo);item.remove();updatePhotoStatus()});$('#photoTray').append(item)}function updatePhotoStatus(){const count=activePet().photos.length;$('#chatStatus').textContent=count?`${count} photo${count>1?'s':''} attached · ${count===1?'enough to create a twin':count>=3?'great detail coverage':'extra detail added'}`:'Upload one photo to start · extra angles are optional'}
$('#sendPhotoMessage').addEventListener('click',()=>{const input=$('#photoMessage'),message=input.value.trim();if(!message&&!activePet().photos.length){$('#petPhotos').click();return}if(message){activePet().note=message;const bubble=document.createElement('div');bubble.className='chat-bubble user';bubble.textContent=message;$('#photoChat').insertBefore(bubble,$('.shot-guide'));input.value=''}const reply=document.createElement('div');reply.className='chat-bubble assistant compact';reply.innerHTML=`<span class="chat-mark">P</span><p>${activePet().photos.length?'Perfect—this is enough to start. Any extra angle is completely optional.':'Got it. Add one clear photo whenever you’re ready.'}</p>`;$('#photoChat').append(reply);toast('Message added to pet profile')});$('#photoMessage').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendPhotoMessage').click()});
$('#createTwin').addEventListener('click',async e=>{const pet=activePet(),error=$('#twinError');error.textContent='';if(!pet.photos.length){error.textContent='Add at least one photo so we have a likeness to work from.';$('#photoChat').classList.add('needs-photo');setTimeout(()=>$('#photoChat').classList.remove('needs-photo'),700);return}const btn=e.currentTarget,status=$('#twinStatus');btn.disabled=true;for(const message of ['Reading body shape…','Matching face features…','Estimating real-world scale…']){status.textContent=message;await new Promise(r=>setTimeout(r,420))}pet.twinReady=true;status.textContent=pet.photos.length>=3?'Size confidence · 92%':'Size confidence · 78%';status.classList.remove('pending');$('#petModel').animate([{transform:'translateX(-50%) scale(.72)',opacity:.2},{transform:'translateX(-50%) scale(1.14)',opacity:1},{transform:'translateX(-50%) scale(1.08)',opacity:1}],{duration:900,easing:'cubic-bezier(.2,.8,.2,1)'});btn.disabled=false;btn.innerHTML='Pet twin ready <span>✓</span>';toast(`${pet.name}'s pet twin is ready`)});$('#rotatePet').addEventListener('click',()=>$('#petModel').classList.toggle('flipped'));$('#adjustFit').addEventListener('click',()=>{$('#measurements').classList.add('open');$('#measureToggle').setAttribute('aria-expanded','true');$('#studio').scrollIntoView({behavior:'smooth'});toast('Measurements opened')});
$$('.style').forEach(btn=>btn.addEventListener('click',()=>{$$('.style').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const canvas=$('#portraitCanvas');canvas.className='portrait-canvas '+(btn.dataset.style==='storybook'?'':btn.dataset.style)}));$$('.palette button[data-color]').forEach(btn=>btn.addEventListener('click',()=>{document.documentElement.style.setProperty('--clay',btn.dataset.color);toast('Brand color updated')}));$$('.brand-output-tabs span').forEach((tab,i)=>tab.addEventListener('click',()=>{$$('.brand-output-tabs span').forEach(x=>x.classList.remove('active'));tab.classList.add('active');$('#portraitCanvas').dataset.view=['mark','wordmark','pattern'][i];toast(`${tab.textContent} preview`)}));
$('#generatePattern').addEventListener('click',async e=>{if(!activePet().twinReady){toast('Create the pet twin first so the brand keeps their likeness');$('#studio').scrollIntoView({behavior:'smooth'});return}const btn=e.currentTarget;btn.disabled=true;for(const message of ['Drawing portrait mark…','Setting name lockup…','Tiling the repeat pattern…']){btn.innerHTML=`${message} <span>✦</span>`;await new Promise(r=>setTimeout(r,430))}state.brandReady=true;$('#portraitCanvas').classList.add('brand-ready');$('#brandKitResult').classList.add('ready');$('#applyBrand').disabled=false;btn.disabled=false;btn.innerHTML='Brand kit ready <span>✓</span>';toast(`${activePet().name}'s brand kit is ready`)});$('#applyBrand').addEventListener('click',()=>{$$('.branded-surface').forEach(x=>x.classList.add('brand-applied'));$('#collection').scrollIntoView({behavior:'smooth'});toast('Brand applied to products for both of you')});
$$('.filters button').forEach(btn=>btn.addEventListener('click',()=>{$$('.filters button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$$('.collection .product').forEach(p=>p.classList.toggle('hidden',btn.dataset.filter!=='all'&&p.dataset.category!==btn.dataset.filter))}));let selectedProduct=null;$$('.customize-product').forEach(btn=>btn.addEventListener('click',()=>{selectedProduct=btn.closest('.product');$('#customizerTitle').textContent=selectedProduct.dataset.product;$('#pdpLink').href=`product.html?product=${selectedProduct.dataset.slug}&pet=${encodeURIComponent(activePet().name)}`;$('#customizer').classList.add('open');$('#customizer').setAttribute('aria-hidden','false')}));$('#closeCustomizer').addEventListener('click',()=>{$('#customizer').classList.remove('open');$('#customizer').setAttribute('aria-hidden','true')});$$('.mini-palette button').forEach(btn=>{btn.style.background=btn.dataset.color;btn.addEventListener('click',()=>$('.customizer-swatch').style.backgroundColor=btn.dataset.color)});$('#saveCustomization').addEventListener('click',()=>{if(!selectedProduct)return;selectedProduct.classList.add('customized');selectedProduct.querySelector('.customize-product').textContent='Customized ✓';$('#customizer').classList.remove('open');state.bag++;$('#bagCount').textContent=state.bag;toast(`${selectedProduct.dataset.product} customized for ${activePet().name}`)});$$('.owner-mode button').forEach(btn=>btn.addEventListener('click',()=>{$$('.owner-mode button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('#for-you').dataset.mode=btn.dataset.ownerMode;toast(`${btn.textContent} treatment applied to owner products`)}));
$$('.home-tabs button').forEach(btn=>btn.addEventListener('click',()=>{$$('.home-tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('#roomScene').className='room '+btn.dataset.room;$('.room-label b').textContent={sleep:'Golden hour garden',walk:'Ready for the park',dine:'Sunday supper'}[btn.dataset.room]}));$('#saveRoom').addEventListener('click',e=>{e.currentTarget.innerHTML='Room saved <span>♥</span>';toast(`Saved to ${activePet().name}'s home`)});$('#bagButton').addEventListener('click',()=>toast(state.bag?`${state.bag} customized piece${state.bag>1?'s':''} saved`:'Customize a piece to start your bag'));syncPetUI();
